import{_ as n,l as s,o as g,b as r,q as o,d,f as t,m as i,j as a}from"./chunks/framework.Tf23FRXt.js";const u="/assets/7d0e60ab4f68e5c00b0392bd035710c25677f4.BilZH-Lt.jpg",v="/assets/ebd8dfc7d8b9249c66619e59d9dc105d4908e7.C_uZ35kX.jpg",b="/assets/278017494dae21956b2e0de790bf742749688b.7mXJNdn5.jpg",m="/assets/c8274ef22c511b418117f7f6d2305860edaef1.Dv3DQ4wj.jpg",f="/assets/a772ab2601e782e88a8f141dd22a616b3d4234.DFnaxx4N.jpg",_="/assets/d8e21209dfd1e6b51e6f323aa5417764c86913.BBMLwPUM.jpg",y="/assets/926a52e67f0b0a9bd366ea8024bb0812dbdd4f.QHJqnGIw.jpg",w="/assets/81af75bf504bff1c1b35569f8f867dfdf1c518.inZdP1Dj.jpg",T="/assets/0153a1a40ccd0c9aeeb78038f18acd0032a5c4.BiGV4lJL.jpg",j="/assets/cca2b6f76fd102b40d4111db88bceb81e06d5a.CEALDf4Y.jpg",C="/assets/18b011e06581655d673a946dae47a5610398cd.0MBHMyyF.jpg",x="/assets/01687342aeb9be2eff57fe02d8bffa93e1349e.Cho3SWAm.jpg",z="/assets/22fb77e15d92eb1058484054afa943c8fbb889.CBwyLRcI.jpg",N="/assets/3f19cf1e966b19ec5fa13c7bba79d7c01bdba6.CiGr_Qtw.jpg",P="/images/icons/061523.png",S="/assets/b933d6ae302ca1fa32b19ad7b73fd0fb818213.D_9sPVA6.jpg",A="/assets/39f199fcd617d52d6695249b85145cf6d420c7.C2kTE6Cd.jpg",B="/images/icons/061537.png",J=JSON.parse('{"title":"玩家交流","description":"","frontmatter":{},"headers":[{"level":2,"title":"名牌","slug":"名牌","link":"#名牌","children":[]},{"level":2,"title":"聊天","slug":"聊天","link":"#聊天","children":[{"level":3,"title":"聊天窗口的设置","slug":"聊天窗口的设置","link":"#聊天窗口的设置","children":[]}]},{"level":2,"title":"新人频道","slug":"新人频道","link":"#新人频道","children":[]}],"relativePath":"basic/communication.htm.md","filePath":"basic/communication.md","lastUpdated":1791101830000}'),D={name:"basic/communication.htm.md"},V={class:"guide cols2"},k={class:"guide col grow"};function h(I,l,M,E,L,q){const e=s("CollapseText"),p=s("quest"),c=s("SegmentText");return g(),r("div",null,[l[14]||(l[14]=o('<h1 id="玩家交流" tabindex="-1">玩家交流</h1><p>在 FF14 的世界中，有大量和我们一样的玩家，也有原本就生活在这个世界中的非玩家角色（NPC）。利用名牌的颜色区分玩家，和大家友好地交流吧！</p><h2 id="名牌" tabindex="-1">名牌</h2><div class="guide cols2"><div class="guide col"><p><img src="'+u+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>区分目标角色是玩家还是 NPC 的方法，就是查看角色头顶名牌的颜色。</p><p>在默认情况下，浅绿色的是 NPC，而蓝色的则是其他玩家操作的角色。</p></div></div><div class="guide cols2"><div class="guide col"><p><img src="'+v+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>自己看到他人名牌的颜色，会根据自己与对方的关系不同而发生变化。</p><p>默认情况下，对方如果是好友的话，名牌就是橙色，如果是小队成员的话，则是浅蓝色。</p></div></div><div class="guide cols2"><div class="guide col"><p><img src="'+b+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>角色名牌的颜色可以通过快捷指令 &gt; 系统 &gt; 角色设置 &gt; 名牌设置中的各个标签进行改变。</p><p>选择想要改变颜色的对象，点击后就会打开调色板，选一个你中意的颜色吧。</p><p>Tips：每项下面的下拉菜单可以改变名牌显示的规则。如果看不清画面的话，可以在这里将部分名牌设置为不显示。</p></div></div><h2 id="聊天" tabindex="-1">聊天</h2><p>在最终幻想 14 里，可以通过聊天窗口轻松地与其他冒险者进行聊天。和其他玩家交流是 MMO 游戏的精髓，放心大胆地发言吧！</p><p>游戏内的聊天，根据聊天对象的距离、所属分组而区分了很多对话频道。因此，需要选择恰当的对话频道与交流对象进行交谈。使用文本指令的话，不切换频道也可以快速在指定频道发言。</p><div class="md-table"><table class="ui compact grey striped unstackable table"><thead><tr><th>交流频道</th><th>目标对象</th><th>可见范围</th><th>文本指令</th></tr></thead><tbody><tr><td>说话 (/s)</td><td>自身周边小范围的人</td><td>仅限自己周围小范围</td><td>/ 说 你好！<br>/s 你好！</td></tr><tr><td>呼喊 (/y)</td><td>自身周边大范围的人</td><td>仅限自己周边大范围</td><td>/ 呼 你好！<br>/y 你好！</td></tr><tr><td>喊话 (/sh)</td><td>同一地图的所有角色</td><td>自己所在的地区</td><td>/ 喊 你好！<br>/sh 你好！</td></tr><tr><td>悄悄话 (/t)</td><td>指定的 1 名角色</td><td>无论对方在哪都可以看到</td><td>/ 悄 角色名 @服务器名 你好！<br>/t 角色名 @服务器名 你好！</td></tr><tr><td>小队 (/p)</td><td>小队成员<br>适合在副本中与队员交流</td><td>无论对方在哪都可以看到</td><td>/ 队 你好！<br>/p 你好！</td></tr><tr><td>团队 (/a)</td><td>团队成员<br>适合在副本中与团队成员交流</td><td>无论对方在哪都可以看到</td><td>/ 团 你好！<br>/a 你好！</td></tr><tr><td>部队 (/fc)</td><td>所属部队成员</td><td>无论对方在哪都可以看到</td><td>/ 部 你好！<br>/fc 你好！</td></tr><tr><td>通讯贝 (/l [编号])<br>例：/l1、/l2</td><td>所属通讯贝成员<br>适合与朋友闲聊</td><td>无论对方在哪都可以看到</td><td>/ 讯 [编号] 你好！<br>/l [编号] 你好！</td></tr><tr><td>跨服通讯贝 (/cwl [编号])<br>例：/cwl1、/cwl2</td><td>所属跨服通讯贝成员</td><td>无论对方在哪都可以看到</td><td>/ 跨 [编号] 你好！<br>/cwl [编号] 你好！</td></tr><tr><td>新人频道 (/b)</td><td>新人频道成员</td><td>无论对方在哪都可以看到</td><td>/ 新 你好！<br>/b 你好！</td></tr></tbody></table></div><p>不管向哪个频道说话，都要使用聊天窗口。</p><h5 id="来试试聊天吧" tabindex="-1">来试试聊天吧！</h5><ol><li>从左边的小气泡按钮中选择想要发言的交流频道！</li></ol><div class="guide cols2"><div class="guide col"><p><img src="'+m+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>点击聊天窗口左下角的小气泡按钮，会弹出子命令菜单，从中选择想要使用的交流频道。</p><p>※如果你没有加入对应组别，有部分频道可能不会显示。<br> ※选择频道之后，输入框上方会显示频道名。</p></div></div><ol start="2"><li>按 <code>回车</code> 键，或者单击输入框就可以输入了！</li></ol>',15)),d("div",V,[l[4]||(l[4]=d("div",{class:"guide col"},[d("p",null,[d("img",{src:f,alt:"",loading:"lazy"})])],-1)),d("div",k,[l[1]||(l[1]=d("p",null,"向各个频道发言的方法，根据你是否开启了直接聊天模式而有所区别。",-1)),l[2]||(l[2]=d("p",null,[d("strong",null,"未开启直接聊天模式"),d("br"),t(" 🖱 先按下 "),d("code",null,"回车"),t(" 键或单击输入框，然后输入想说的话。🎮 先按 "),d("code",null,"BACK"),t(" 键激活输入框，然后输入想说的话。")],-1)),l[3]||(l[3]=d("p",null,[d("strong",null,"开启直接聊天模式"),d("br"),t(" 直接输入想说的话。")],-1)),i(e,{summary:"直接聊天模式是什么？"},{default:a(()=>[...l[0]||(l[0]=[d("p",null,"在角色设置 > 操作设置中的设置聊天模式可以打开直接聊天模式，通常推荐手柄玩家使用直接聊天模式。键鼠模式的玩家开启直接聊天模式，会严重地影响游戏正常进行。",-1)])]),_:1})])]),l[15]||(l[15]=o('<ol start="3"><li>再次按下 <code>回车</code> 键，就可以发送聊天内容了！</li></ol><div class="guide cols2"><div class="guide col"><p><img src="'+_+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>输入完内容之后，再次按 <code>回车</code> 键，就可以向指定频道发送内容了！</p><p>※聊天窗口中也会出现自己的发言。</p></div></div><div class="guide cols2"><div class="guide col"><p><img src="'+y+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>不选择特定的对象，想跟周围的人聊天时，可以使用【说话】【呼喊】【喊话】频道！</p><p>不同频道可传播的距离是不一样的。</p><p>【说话】频道只能传播到周围很小范围的人群，而【呼喊】的传播范围要比【说话】大得多，而【喊话】频道的发言可以传播到当前地图的每一个角落。</p></div></div><div class="guide cols2"><div class="guide col"><p><img src="'+w+'" alt="" loading="lazy"></p></div><div class="guide col"><p><img src="'+T+'" alt="" loading="lazy"></p></div></div><p>只想两个人说悄悄话的时候，就使用【悄悄话】频道吧！</p><p>只要对方在线，无论他在哪里，都能收到【悄悄话】频道的聊天信息（在副本战斗、剧情动画中，会提示无法使用悄悄话功能）。</p><p><strong>开始聊天的方法</strong></p><ol><li>右键聊天对象的角色名，选【择发送悄悄话】！</li><li>输入文字！</li><li>按 <code>回车</code> 键发送！</li></ol><h3 id="聊天窗口的设置" tabindex="-1">聊天窗口的设置</h3><p>消息窗口的文字尺寸，可以在菜单 &gt; 系统 &gt; 角色设置 &gt; 消息窗口设置中的字体大小中设置。</p><div class="guide cols2"><div class="guide col"><p><img src="'+j+'" alt="" loading="lazy"></p></div><div class="guide col"><p><img src="'+C+'" alt="" loading="lazy"></p></div></div><p>Tips：同一个地方还有消息窗口透明度的设置，如果背景太亮看不清字，可以适当调低。</p><p>分不清聊天内容的时候，也可以单独修改某一个聊天频道的文字颜色！</p><ol><li>角色设置 &gt; 消息窗口设置 &gt; 全体选项卡中找到信息颜色设置！</li></ol><div class="guide cols2"><div class="guide col"><p><img src="'+x+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>角色设置 &gt; 消息窗口设置 &gt; 全体选项卡中找到信息颜色设置。</p></div></div><ol start="2"><li>在信息颜色设置中选择想要改变颜色的地方，从跳出的 “颜色选择” 窗口中选择颜色！</li></ol><div class="guide cols2"><div class="guide col"><p><img src="'+z+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>在信息颜色设置中选择想要改变颜色的地方，从跳出的 “颜色选择” 窗口中选择颜色。</p><p>※选择好信息颜色之后，对应部分的颜色图标也会改变颜色。</p></div></div><ol start="3"><li>在信息颜色设置中点击【确认】按钮就完成了！</li></ol><div class="guide cols2"><div class="guide col"><p><img src="'+N+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>想要保存新设置的信息颜色的话，点击【确认】按钮就可以了。</p></div></div><h2 id="新人频道" tabindex="-1">新人频道</h2><p>当玩家初次进入游戏之后，ID 前会获得一个<img src="'+P+'" class="no-zoom sm-icon">豆芽标识，这就意味着这是一名 “新人玩家”。有豆芽标识的玩家就可以受邀请加入新人频道：</p><div class="guide cols2"><div class="guide col"><p><img src="'+S+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>新人频道是为了帮助刚刚开始冒险的新人而准备的专用频道。</p><p>在这个频道里，会有被称作 “指导者” 的老练冒险家，遇到不明白的事情就问他们吧！</p><p>另外，和其他新人一起交流，互相帮助，一定能建立起新的友谊。</p></div></div><div class="guide cols2"><div class="guide col"><p><img src="'+A+'" alt="" loading="lazy"></p></div><div class="guide col grow"><p>只有接受了身为 “指导者” 的老练冒险家的邀请，才能够加入新人频道。</p><p>收到邀请，会弹出一个专用窗口，点击 “加入新人频道” 就可以了。</p></div></div><p>连续 45 天以上未上线的玩家，并且有任意职业大于等于 50 级，上线后会获得<img src="'+B+'" class="no-zoom sm-icon">豆花标识，这意味着这是一名 “回归者”，有回归者标识的玩家会自动加入新人频道。</p>',24)),i(c,{className:"blue"},{default:a(()=>[l[13]||(l[13]=d("h3",{id:"如何退出新人频道",tabindex:"-1"},"如何退出新人频道",-1)),d("ul",null,[d("li",null,[l[11]||(l[11]=t("新人（豆芽）玩家： ",-1)),d("ul",null,[d("li",null,[l[5]||(l[5]=t("游戏时间超过 (12.5 天 * 24=) 300 小时，并且完成 90 级最后一个主线任务",-1)),i(p,{name:"迈向明日的一步"}),l[6]||(l[6]=t("就会自动解除新人状态并退出新人频道（俗称脱芽、摘芽）。 ",-1)),l[7]||(l[7]=d("ul",null,[d("li",null,[t("输入 "),d("code",null,"/游戏时间"),t(" 可以查询当前的游戏时间。")])],-1))]),l[8]||(l[8]=d("li",null,[t("输入 "),d("code",null,"/退出新人频道"),t(" ：可以直接退出新人频道。")],-1)),l[9]||(l[9]=d("li",null,[t("输入 "),d("code",null,"/新人状态 off"),t(" ：可以关闭新人状态并自动退出新人频道。")],-1)),l[10]||(l[10]=d("li",null,[t("输入 "),d("code",null,"/新人邀请 off"),t(" ：可以自动拒绝新人频道加入邀请。")],-1))])]),l[12]||(l[12]=d("li",null,[t("回归者（豆花）玩家： "),d("ul",null,[d("li",null,"回归后游戏累计时长超过 72 小时则自动解除回归者状态。"),d("li",null,[t("输入 "),d("code",null,"/解除回归者状态"),t(" ：可以直接解除回归者状态。")])])],-1))])]),_:1})])}const $=n(D,[["render",h]]);export{J as __pageData,$ as default};
